  // Value class
  class Value {
    constructor (start, end, inc) {
        this.start = start;
        this.end = end;
        this.inc = inc;
        this.value = 0;
    }
  
    add() {
        if (this.value < this.end) {
            this.value += this.inc;
        } else {
            this.value = this.start;
